<?php declare(strict_types=1);
$tables=[];try{$tables=$db->query("SELECT TABLE_NAME,TABLE_ROWS,ENGINE,TABLE_COLLATION,ROUND((DATA_LENGTH+INDEX_LENGTH)/1024/1024,2) size_mb FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
$views=count($tables);$totalRows=0;$totalMb=0;foreach($tables as $r){$totalRows+=(int)($r['TABLE_ROWS']??0);$totalMb+=(float)($r['size_mb']??0);}
?>
<div class="av4-page"><div class="av4-stat-grid"><div class="av4-stat purple"><b><?=number_format($views)?></b><span>Tables</span></div><div class="av4-stat"><b><?=number_format($totalRows)?></b><span>Approx. rows</span></div><div class="av4-stat blue"><b><?=number_format($totalMb,2)?> MB</b><span>Data + index size</span></div><div class="av4-stat green"><b><?=av4h((string)$db->getAttribute(PDO::ATTR_DRIVER_NAME))?></b><span>Driver</span></div></div>
<div class="av4-card"><div class="av4-head"><div><h2>🗄️ Database Explorer</h2><p>Schema visibility, row estimates, storage and direct table browsing.</p></div><a class="av4-btn primary" href="/smart-toolz/admin/db-browser.php">Open Full Explorer ↗</a></div><div class="av4-note">This admin view is intentionally read-only. Use the dedicated DB Explorer to browse table structures and rows. No database credentials are exposed to the browser.</div></div>
<div class="av4-card"><div class="av4-head"><div><h2>Database tables</h2><p><?=number_format($views)?> tables detected in the current database.</p></div></div><div class="av4-table"><table><thead><tr><th>Table</th><th>Engine</th><th>Rows</th><th>Size</th><th>Collation</th><th>Browse</th></tr></thead><tbody><?php foreach($tables as $r):?><tr><td><b><?=av4h($r['TABLE_NAME'])?></b></td><td><?=av4h($r['ENGINE'])?></td><td><?=number_format((int)$r['TABLE_ROWS'])?></td><td><?=av4h($r['size_mb'])?> MB</td><td><?=av4h($r['TABLE_COLLATION'])?></td><td><a class="av4-btn small" href="/smart-toolz/admin/db-browser.php?table=<?=rawurlencode((string)$r['TABLE_NAME'])?>">Browse ↗</a></td></tr><?php endforeach;if(!$tables):?><tr><td colspan="6" class="empty">Could not read database schema.</td></tr><?php endif;?></tbody></table></div></div></div>
